import { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Filters } from '@/types/table.types';
import { EmployeeSalary } from '../../types/employeeSalary.types';

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => ({
    label: String(i + 1),
    value: String(i + 1),
}));

function buildYearOptions(centerYear: number) {
    const years: { label: string; value: string }[] = [];
    for (let y = centerYear - 5; y <= centerYear + 5; y++) {
        years.push({ label: String(y), value: String(y) });
    }
    return years;
}

export interface EmployeeSalaryDetailsToolbarProps {
    table: Table<EmployeeSalary>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    handleRefreshTable?: () => void;
    data?: EmployeeSalary[];
    payrollMonth: number;
    payrollYear: number;
    onPayrollMonthYearChange: (month: number, year: number) => void;
}

export function DataTableToolbar({
    globalFilter,
    setGlobalFilter,
    payrollMonth,
    payrollYear,
    onPayrollMonthYearChange,
}: EmployeeSalaryDetailsToolbarProps) {
    const yearOptions = buildYearOptions(payrollYear);

    return (
        <>
            <div className="flex flex-col p-2 gap-3 sm:flex-row sm:items-center sm:justify-between">
                <UnderlineHeading text="تفاصيل عناصر المرتب" />
                <div className="flex w-full sm:w-auto flex-wrap items-center gap-3 sm:justify-end">
                    <div className="flex flex-wrap items-center gap-2">
                        <span className="text-sm text-primery-blue-700 whitespace-nowrap">الفترة:</span>
                        <CustomSelect
                            value={String(payrollMonth)}
                            onValueChange={(v) => onPayrollMonthYearChange(Number(v), payrollYear)}
                            placeholder="الشهر"
                            width="min-w-[88px]"
                            options={MONTH_OPTIONS}
                        />
                        <CustomSelect
                            value={String(payrollYear)}
                            onValueChange={(v) => onPayrollMonthYearChange(payrollMonth, Number(v))}
                            placeholder="السنة"
                            width="min-w-[100px]"
                            options={yearOptions}
                        />
                    </div>
                    <div className="flex flex-row items-center w-full sm:w-[287px] border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                        <Input
                            placeholder="بحث في الاسم أو البريد"
                            value={globalFilter}
                            onChange={(event) => setGlobalFilter(event.target.value)}
                            className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                        />
                        <button type="button" className="bg-transparent border-none">
                            <SearchIcon className="text-white-blue-800" />
                        </button>
                    </div>
                    <div className="flex items-center justify-center gap-2 px-[14px] py-2 bg-primery-blue-50 border border-primery-blue-50 shadow-[0px_1px_2px_0px_#1018280D] rounded-lg ">
                        <ArrowBackIcon className="text-primery-blue-700" />
                        <p className="text-xs text-primery-blue-500 tracking-normal font-normal leading-[22.49px]">
                            تصدير
                        </p>
                    </div>
                </div>
            </div>
        </>
    );
}
