import StatisticsCards from '@/components/cards/StatisticsCards';
import PeopleIcon from '@/components/icons/PeopleIcon';
import TwoUserIcon from '@/components/icons/TwoUsersIcon';
import UserMinusIcon from '@/components/icons/UserMinusIcon';
import UserRemoveIcon from '@/components/icons/UserRemoveIcon';
import { Gift } from 'lucide-react';
import { Card } from '@/types/statistics';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';

interface Props {
    month: number;
    year: number;
}

export default function EmployeeSalaryDetailsStatistics({ month, year }: Props) {
    const { id } = useParams();
    const [basicSalary, setBasicSalary] = useState(0);
    const [allowances, setAllowances] = useState(0);
    const [deductions, setDeductions] = useState(0);
    const [rewards, setRewards] = useState(0);
    const [netSalary, setNetSalary] = useState(0);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!id) return;
            try {
                const res = await apiGet({
                    endpoint: endpoints.employee.salary + id,
                    queryParams: { month, year },
                });
                const d = res.data.data as {
                    basic_salary?: number;
                    total_allowances?: number;
                    total_deductions?: number;
                    total_rewards?: number;
                    net_salary?: number;
                };
                if (!cancelled) {
                    setBasicSalary(Number(d.basic_salary) || 0);
                    setAllowances(Number(d.total_allowances) || 0);
                    setDeductions(Number(d.total_deductions) || 0);
                    setRewards(Number(d.total_rewards) || 0);
                    setNetSalary(Number(d.net_salary) || 0);
                }
            } catch {
                if (!cancelled) {
                    setBasicSalary(0);
                    setAllowances(0);
                    setDeductions(0);
                    setRewards(0);
                    setNetSalary(0);
                }
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [id, month, year]);

    const cards: Card[] = useMemo(
        () => [
            { text: 'الراتب الأساسي', num: basicSalary.toLocaleString('en-US'), icon: <PeopleIcon />, label: 'ريال', percent: 0 },
            { text: 'الحوافز و البدلات', num: allowances.toLocaleString('en-US'), icon: <TwoUserIcon />, label: 'ريال', percent: 0 },
            { text: 'المكافآت', num: rewards.toLocaleString('en-US'), icon: <Gift className="h-6 w-6" />, label: 'ريال', percent: 0 },
            { text: 'الخصومات', num: deductions.toLocaleString('en-US'), icon: <UserMinusIcon />, label: 'ريال', percent: 0 },
            { text: 'صافي الراتب', num: netSalary.toLocaleString('en-US'), icon: <UserRemoveIcon />, label: 'ريال', percent: 0 },
        ],
        [basicSalary, allowances, deductions, rewards, netSalary],
    );

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
