import { ColumnDef, Row } from '@tanstack/react-table';
import adel from '@/assets/imgs/user.png';
import ViewIcon from '@/components/icons/ViewIcon';
import { Link } from 'react-router-dom';
import { EmployeeSalary } from '../../types/employeeSalary.types';

function fmtCell(n: number | undefined | null) {
    if (n === undefined || n === null || Number.isNaN(Number(n))) return '—';
    return Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

const ActionsCell = ({ row }: { row: Row<EmployeeSalary> }) => {
    return (
        <div className="cursor-pointer flex justify-center">
            <Link to={`/human-resources/employee/${row.original.id}`}>
                <ViewIcon className="text-primery-blue-400" />
            </Link>
        </div>
    );
};

export const columns: ColumnDef<EmployeeSalary>[] = [
    {
        accessorKey: 'name',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                اسم الموظف
            </div>
        ),
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <img src={adel} alt="" className="rounded-full w-10 h-10 object-cover" />
                <div className="flex flex-col gap-1">
                    <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.name}</p>
                    <p className="tracking-normal text-white-blue-800 font-normal text-sm">{row.original.email}</p>
                </div>
            </div>
        ),
    },
    {
        accessorKey: 'total_allowances',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                عناصر الراتب
            </div>
        ),
        cell: () => {
            const lines = ['الراتب الأساسي', 'البدلات والحوافز', 'المكافآت', 'الخصومات', 'صافي الراتب'];
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    <div className="flex flex-col gap-1">
                        {lines.map((t) => (
                            <p key={t} className="text-primery-blue-900 font-medium text-sm">
                                {t}
                            </p>
                        ))}
                    </div>
                </div>
            );
        },
    },
    {
        accessorKey: 'net_salary',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">ر.س</div>
        ),
        cell: ({ row }) => {
            const basic = Number(row.original.basic_salary ?? row.original.contract?.salary ?? row.original.salary?.salary ?? 0) || 0;
            const allowances = Number(row.original.total_allowances) || 0;
            const rewards = Number(row.original.total_rewards) || 0;
            const deductions = Number(row.original.total_deductions) || 0;
            const net = Number(row.original.net_salary) || 0;
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                    <div className="flex flex-col gap-1">
                        <p>{fmtCell(basic)}</p>
                        <p>{fmtCell(allowances)}</p>
                        <p>{fmtCell(rewards)}</p>
                        <p>{fmtCell(deductions)}</p>
                        <p className="font-semibold text-primery-blue-900">{fmtCell(net)}</p>
                    </div>
                </div>
            );
        },
    },
    {
        id: 'actions',
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
