import adel from '@/assets/imgs/user.png';
import { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { EmployeeSalary } from '../../types/employeeSalary.types';

function fmt(n: number | undefined | null) {
    if (n === undefined || n === null || Number.isNaN(Number(n))) return '—';
    return `${Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 })} ر.س`;
}

interface Props {
    month: number;
    year: number;
}

export default function EmployeeInfo({ month, year }: Props) {
    const { id } = useParams();
    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<EmployeeSalary | null>(null);

    const employeeId = useMemo(() => (id ? String(id) : ''), [id]);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!employeeId) return;
            setLoading(true);
            try {
                const res = await apiGet<{ data: EmployeeSalary }>({
                    endpoint: endpoints.employee.salary + employeeId,
                    queryParams: { month, year },
                });
                if (!cancelled) setData(res.data.data);
            } catch {
                if (!cancelled) setData(null);
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [employeeId, month, year]);

    const periodLabel = `${String(month).padStart(2, '0')}/${year}`;

    return (
        <>
        <div className="flex flex-col lg:flex-row flex-wrap items-stretch w-full mt-6 gap-0 border border-[#E8E7EA] rounded-lg overflow-hidden">
            <div className="flex-1 min-w-[140px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    اسم الموظف
                </p>
                <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    <img src={adel} alt="" className="rounded-full w-10 h-10 object-cover" />
                    <div className="flex flex-col gap-1 text-nowrap">
                        <p className="tracking-normal text-primery-blue-900 font-medium text-sm">
                            {loading ? 'جاري التحميل…' : data?.name || '—'}
                        </p>
                        <p className="tracking-normal text-white-blue-800 font-normal text-sm">
                            {data ? `${data.position} — ${data.branch?.name ?? ''}` : '—'}
                        </p>
                    </div>
                </div>
            </div>
            <div className="flex-1 min-w-[120px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    كود الموظف
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">{data?.id ?? '—'}</p>
            </div>
            <div className="flex-1 min-w-[120px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    الفترة
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">{periodLabel}</p>
            </div>
            <div className="flex-1 min-w-[120px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    القسم
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {data?.department ?? data?.branch?.name ?? '—'}
                </p>
            </div>
            <div className="flex-1 min-w-[120px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    المسمى الوظيفي
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">{data?.position ?? '—'}</p>
            </div>
            <div className="flex-1 min-w-[120px] border-b lg:border-b-0 lg:border-e border-[#E8E7EA]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    تاريخ التعيين
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">{data?.hire_date ?? '—'}</p>
            </div>
            <div className="flex-1 min-w-[140px]">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    ملخص الراتب (الفترة)
                </p>
                <div className="text-xs text-[#625E74] font-normal tracking-normal leading-[140%] p-4 space-y-1">
                    <p>أساسي: {fmt(data?.basic_salary)}</p>
                    <p>بدلات: {fmt(data?.total_allowances)}</p>
                    <p>مكافآت: {fmt(data?.total_rewards)}</p>
                    <p>خصومات: {fmt(data?.total_deductions)}</p>
                    <p className="font-semibold text-primery-blue-900 pt-1">صافي: {fmt(data?.net_salary)}</p>
                </div>
            </div>
        </div>
        {!loading && data?.rewards && data.rewards.length > 0 ? (
            <div className="mt-6 w-full rounded-lg border border-[#E8E7EA] overflow-hidden">
                <p className="text-sm px-4 py-3 bg-white-blue-100 font-semibold text-primery-blue-500">المكافآت في هذه الفترة</p>
                <table className="w-full text-sm">
                    <thead>
                        <tr className="bg-white-blue-50 text-primery-blue-700">
                            <th className="text-start p-3 font-medium">التاريخ</th>
                            <th className="text-start p-3 font-medium">المبلغ</th>
                            <th className="text-start p-3 font-medium">السبب</th>
                        </tr>
                    </thead>
                    <tbody>
                        {data.rewards.map((r) => (
                            <tr key={r.id} className="border-t border-[#E8E7EA] text-[#625E74]">
                                <td className="p-3">{r.date ?? '—'}</td>
                                <td className="p-3">{fmt(r.amount)}</td>
                                <td className="p-3">{r.reason}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        ) : null}
        {!loading && data?.allowance_rows && data.allowance_rows.length > 0 ? (
            <div className="mt-6 w-full rounded-lg border border-[#E8E7EA] overflow-hidden">
                <p className="text-sm px-4 py-3 bg-white-blue-100 font-semibold text-primery-blue-500">البدلات والخصومات (تفاصيل)</p>
                <table className="w-full text-sm">
                    <thead>
                        <tr className="bg-white-blue-50 text-primery-blue-700">
                            <th className="text-start p-3 font-medium">التاريخ</th>
                            <th className="text-start p-3 font-medium">النوع</th>
                            <th className="text-start p-3 font-medium">المبلغ</th>
                            <th className="text-start p-3 font-medium">البيان</th>
                        </tr>
                    </thead>
                    <tbody>
                        {data.allowance_rows.map((a) => (
                            <tr key={a.id} className="border-t border-[#E8E7EA] text-[#625E74]">
                                <td className="p-3">{a.date ?? '—'}</td>
                                <td className="p-3">{a.allowance_type === 'deductions' ? 'خصم' : 'بدل'}</td>
                                <td className="p-3">{fmt(a.amount)}</td>
                                <td className="p-3">{a.name || a.note || '—'}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        ) : null}
        </>
    );
}
