import { useCallback, useMemo, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar, type EmployeeSalaryDetailsToolbarProps } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { useParams } from 'react-router-dom';
import { EmployeeSalary } from '../../types/employeeSalary.types';

type ToolbarPassThrough = Omit<
    EmployeeSalaryDetailsToolbarProps,
    'payrollMonth' | 'payrollYear' | 'onPayrollMonthYearChange'
>;

interface Props {
    month: number;
    year: number;
    onPayrollMonthYearChange: (month: number, year: number) => void;
}

export default function EmployeeSalaryDetailsList({ month, year, onPayrollMonthYearChange }: Props) {
    const [data, setData] = useState<EmployeeSalary[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const { id } = useParams();

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            if (!id) return;
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.employee.salary + id,
                    queryParams: {
                        month,
                        year,
                    },
                });
                const row = response.data.data as EmployeeSalary;
                const q = (options.globalFilter || '').trim().toLowerCase();
                const name = (row.name || '').toLowerCase();
                const email = (row.email || '').toLowerCase();
                const match = !q || name.includes(q) || email.includes(q);
                const rows = match ? [row] : [];
                setData(rows);
                setPageCount(1);
                setTotalCount(rows.length);
            } catch {
                setData([]);
                setPageCount(0);
                setTotalCount(0);
            } finally {
                setIsLoading(false);
            }
        },
        [id, month, year],
    );

    const Toolbar = useMemo(
        () =>
            function EmployeeToolbar(props: ToolbarPassThrough) {
                return (
                    <DataTableToolbar
                        {...props}
                        payrollMonth={month}
                        payrollYear={year}
                        onPayrollMonthYearChange={onPayrollMonthYearChange}
                    />
                );
            },
        [month, year, onPayrollMonthYearChange],
    );

    return (
        <div className="mt-6 mb-20 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                key={`employee-salary-${id}-${month}-${year}`}
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={Toolbar}
                isLoading={isLoading}
                pagination={false}
            />
        </div>
    );
}
