import { useCallback, useState } from 'react';
import EmployeeInfo from '../components/employeeSalaryDetails/EmployeeInfo';
import EmployeeSalaryDetailsList from '../components/employeeSalaryDetails/EmployeeSalaryDetailsList';
import EmployeeSalaryDetailsStatistics from '../components/statistics/EmployeeSalaryDetailsStatistics';

export default function EmployeeSalaryDetails() {
    const [payrollMonth, setPayrollMonth] = useState(() => new Date().getMonth() + 1);
    const [payrollYear, setPayrollYear] = useState(() => new Date().getFullYear());

    const onPayrollMonthYearChange = useCallback((month: number, year: number) => {
        setPayrollMonth(month);
        setPayrollYear(year);
    }, []);

    return (
        <div className="w-full mt-6 mb-20">
            <EmployeeSalaryDetailsStatistics month={payrollMonth} year={payrollYear} />
            <EmployeeInfo month={payrollMonth} year={payrollYear} />
            <EmployeeSalaryDetailsList month={payrollMonth} year={payrollYear} onPayrollMonthYearChange={onPayrollMonthYearChange} />
        </div>
    );
}
